from scipy.ndimage import binary_dilation
edges=[]
for i,a in enumerate(objs):
 for b in objs[i+1:]:
  dil=binary_dilation(a['mask'],structure=np.ones((3,3),bool))
  overlap=np.argwhere(dil & b['mask'])
  if len(overlap): edges.append((a['name'],b['name'],len(overlap),tuple(overlap[0])))
edges

# build adjacency from prior edges, enumerate all simple paths between zero objects
adj={o['name']:set() for o in objs}
for a,b,_,_ in edges:
 adj[a].add(b);adj[b].add(a)
paths=[]
def dfs(cur,target,seen,path):
 if cur==target:
  paths.append(path.copy());return
 for nxt in adj[cur]-seen:
  dfs(nxt,target,seen|{nxt},path+[nxt])
dfs('0-1','0-2',{'0-1'},['0-1'])
len(paths), sorted(set(x for p in paths for x in p)), paths[:5]

